import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv');
for c in x.columns[2:-1]:
 d=x[['recovery_score',c,'hospital']].dropna(); m=smf.ols(f'recovery_score ~ {c} + C(hospital)',d).fit(); print(c, round(m.params[c],3),round(m.pvalues[c],5),round(m.rsquared,3),len(d))

